import{_ as l}from"./chunks/1_resource_20191117164149.CNrfBleH.js";import{_ as i,o as e,c as t,a0 as r}from"./chunks/framework.DqMqoJl9.js";const m=JSON.parse('{"title":"资源优化","description":"","frontmatter":{},"headers":[],"relativePath":"performance/4-resource.md","filePath":"performance/4-resource.md","lastUpdated":1791573371000}'),o={name:"performance/4-resource.md"};function s(h,a,p,n,c,d){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="资源优化" tabindex="-1">资源优化 <a class="header-anchor" href="#资源优化" aria-label="Permalink to &quot;资源优化&quot;">​</a></h1><h2 id="_1-资源压缩与合并" tabindex="-1">1 资源压缩与合并 <a class="header-anchor" href="#_1-资源压缩与合并" aria-label="Permalink to &quot;1 资源压缩与合并&quot;">​</a></h2><h3 id="_1-1-优化思路" tabindex="-1">1.1 优化思路 <a class="header-anchor" href="#_1-1-优化思路" aria-label="Permalink to &quot;1.1 优化思路&quot;">​</a></h3><p>web 前端是 BS 架构。</p><p>BS 架构就是，前端代码开发完成后，将代码发布到远程服务器。然后用户通过浏览器输入网址，这时浏览器向远程服务器发出请求，动态的加载页面的资源。</p><p>因此 web 前端的访问过程是一个动态、增量的加载资源的过程。如果浏览器能越快的获取资源，那么用户就能越快的看到页面，体验也就越好。这是前端性能优化很重要的一个点。</p><p>从资源加载方面优化，需要先分析一下，浏览器的一个请求从发送到返回都经历了什么？</p><p><img src="'+l+'" alt=""></p><p>上图是一个 http 请求发出到响应的过程，在这个过程中可以去挖掘一些可以优化的点，去实现前端的性能优化。</p><p>请求过程中一些潜在的性能优化点：</p><ul><li>dns 是否可以通过缓存减少 dns 查询时间</li><li>网络请求的过程中是否可以走最近的网络环境</li><li>相同的静态资源是否可以缓存</li><li>能否减少 http 请求大小</li><li>减少 http 请求</li><li>服务端渲染</li></ul><h3 id="_1-2-优化点" tabindex="-1">1.2 优化点 <a class="header-anchor" href="#_1-2-优化点" aria-label="Permalink to &quot;1.2 优化点&quot;">​</a></h3><p>资源合并与压缩涉及到的优化点主要有两个，一个是减少 http 请求数量，另外是减少请求资源的大小</p><p>具体的优化点如下：</p><ul><li>html 压缩</li><li>css 压缩</li><li>js 的压缩和混乱</li><li>文件合并</li><li>开启 gzip</li></ul><h3 id="_1-3-html-压缩" tabindex="-1">1.3 html 压缩 <a class="header-anchor" href="#_1-3-html-压缩" aria-label="Permalink to &quot;1.3 html 压缩&quot;">​</a></h3><p>html 代码压缩就是压缩这些在文本文件中有意义，但是在 html 中不显示的字符，包括空格、制表符、换行符等，还有一些其他无意义的字符，如 html 注释也可以被压缩</p><h3 id="_1-4-css-压缩" tabindex="-1">1.4 css 压缩 <a class="header-anchor" href="#_1-4-css-压缩" aria-label="Permalink to &quot;1.4 css 压缩&quot;">​</a></h3><ul><li>无效代码删除（空格、换行、注释等）</li><li>css 语义合并（重复的代码）</li></ul><h3 id="_1-5-js-压缩与混乱" tabindex="-1">1.5 js 压缩与混乱 <a class="header-anchor" href="#_1-5-js-压缩与混乱" aria-label="Permalink to &quot;1.5 js 压缩与混乱&quot;">​</a></h3><ul><li>无效字符的删除</li><li>删除注释</li><li>代码语义的缩减和优化（缩短变量名的长度，删除重复代码等）</li><li>代码保护（js 的代码是透明的，压缩和混淆后可以降低代码的可读性）</li></ul><p>js 和 css 代码压缩不仅能减少文件大小，还有有网站安全方面的收益。并且 js 和 css 的压缩率是比较高的，可以很大程度的减少文件的大小</p><h3 id="_1-6-文件合并" tabindex="-1">1.6 文件合并 <a class="header-anchor" href="#_1-6-文件合并" aria-label="Permalink to &quot;1.6 文件合并&quot;">​</a></h3><p>合并文件可以减少 http 请求的数量。</p><p>请求多个 js 文件跟请求一个 js 文件相比：</p><ul><li>文件与文件之间有插入的上行请求，增加了 N-1 个网络延迟</li><li>受丢包的影响更严重（请求数量更多，丢包的概率更大）</li></ul><p>当然合并文件也不是万能的，合并文件也有它的缺点：</p><ul><li>首屏渲染问题</li><li>缓存失效问题</li></ul><p>文件合并后自然单个文件会变得更大。如果网站是单页面应用，合并文件通常会把公共库还有其他页面的 js 都打包在一起，而首屏渲染需要等待这些资源都加载完成。其中很多资源是首屏页面不需要的。</p><p>缓存失效问题，合并文件会造成大面积的缓存失效。通常当一个文件有改动时才需要重新加载。如果将几个文件合并的话，其中一个文件有改动，那么合并后的文件也会改动，这时就需要重新加载整个文件。而未合并的话只需要重新加载改动的文件就行。</p><p><strong>常用的文件合并策略：</strong></p><ul><li>公共库合并（通常公共库会很少改动，将它们合并更不容易出现缓存失效问题）</li><li>分页面合并（也就是按需加载，不要将所有页面都打包到一起，而是将单个页面所依赖的资源打包，匹配到某个路由的时候只加载这个路由需要的资源）</li></ul><h2 id="_2-图片格式优化" tabindex="-1">2 图片格式优化 <a class="header-anchor" href="#_2-图片格式优化" aria-label="Permalink to &quot;2 图片格式优化&quot;">​</a></h2><h3 id="_2-1-jpeg" tabindex="-1">2.1 jpeg <a class="header-anchor" href="#_2-1-jpeg" aria-label="Permalink to &quot;2.1 jpeg&quot;">​</a></h3><p>JPEG(联合图像专家组 Joint Photographic Experts Group) 。JPEG 编码用来压缩去除冗余的图像和彩色数据，获取得极高的压缩率的同时能展现十分丰富生动的图像。具有调节图像质量的功能，允许你用不同的压缩比例对这种文件压缩。不支持透明度。</p><h3 id="_2-2-png" tabindex="-1">2.2 png <a class="header-anchor" href="#_2-2-png" aria-label="Permalink to &quot;2.2 png&quot;">​</a></h3><p>PNG(便携式网络图形 Portable Network Graphics)。是一种无损压缩的位图图形格式。</p><ul><li>png8 - 256 色，支持透明</li><li>png24 - 2^24 色，不支持透明</li><li>png24 - 2^24 色，不支持透明</li></ul><p>PNG 格式适合保存文本，线条或类似的边缘清晰，有大块相同颜色区域的图像。</p><p>JPEG 采用了一种针对照片图像的特定有损编码方法，这种编码适用于低对比，图像颜色过渡平滑，噪声多，且结构不规则的图像。</p><h3 id="_2-3-不同图片格式常用的业务场景" tabindex="-1">2.3 不同图片格式常用的业务场景 <a class="header-anchor" href="#_2-3-不同图片格式常用的业务场景" aria-label="Permalink to &quot;2.3 不同图片格式常用的业务场景&quot;">​</a></h3><ul><li>jpeg 为有损压缩，压缩率高，不支持透明</li><li>png 为无损压缩，支持透明</li><li>webp 压缩程度更好，在 ios webview 有兼容性问题（安卓上用）</li><li>svg 矢量图，代码内嵌，相对较小。适用图片样式现对简单的场景</li><li>gif 一般用来做动图</li></ul><h2 id="_3-图片加载优化" tabindex="-1">3 图片加载优化 <a class="header-anchor" href="#_3-图片加载优化" aria-label="Permalink to &quot;3 图片加载优化&quot;">​</a></h2><ol><li>转成合适的格式，或对图片进行压缩，针对图片的真实情况，舍弃一些相对无关紧要的色彩信息</li><li>使用 css 雪碧图，将一些图片整合到一张图片中，减少 http 的请求数量（缺点：整合图片比较大时，一次加载比较慢）</li><li>inline image，将图片内嵌在代码中（即转成 base64），通常针对较小的图片</li><li>使用 svg 进行图片的绘制，将图标转成字体。如 <a href="https://www.iconfont.cn/" target="_blank" rel="noreferrer">https://www.iconfont.cn/</a></li></ol><h2 id="_4-字体优化" tabindex="-1">4 字体优化 <a class="header-anchor" href="#_4-字体优化" aria-label="Permalink to &quot;4 字体优化&quot;">​</a></h2>',45)])])}const b=i(o,[["render",s]]);export{m as __pageData,b as default};
